-- Section: Behavioral
INSERT INTO course_sections (id, course_id, title, position)
VALUES ('d3f8c476-a30c-5ea7-b497-dc818ddabea5', '57f5e0f7-67b7-55ab-a3e7-469947105cd5', 'Behavioral', 5)
