VALUES ('9b07474b-dc52-580f-be3d-4716aa9e60b3', '070c855e-b5dc-50ff-9df5-9bc9c1df4fd0', 1, $json${"prompt":"In Django ORM, what is the difference between select_related and prefetch_related?","multiple":false,"options":[{"id":"a","text":"select_related uses a SQL JOIN for foreign keys; prefetch_related runs a second query for many-to-many/reverse relations","is_correct":true},{"id":"b","text":"They are aliases for the same operation","is_correct":false},{"id":"c","text":"prefetch_related joins tables; select_related runs extra queries","is_correct":false},{"id":"d","text":"select_related only works on many-to-many fields","is_correct":false}],"explanation":"select_related follows single-valued relations in one JOINed query; prefetch_related fetches related sets in a separate query and stitches them in Python — both kill N+1 query problems."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
