INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('2e2a4c9d-aa75-51cf-b8f8-3e43b78bdc4c', '7cf1ff49-7579-5a6d-a139-18b8e0121734', 1, $json${"prompt":"What does the CAP theorem say a distributed system must choose between during a network partition?","multiple":false,"options":[{"id":"a","text":"Consistency or availability — you cannot have both while partitioned","is_correct":true},{"id":"b","text":"Latency or throughput","is_correct":false},{"id":"c","text":"Durability or atomicity","is_correct":false},{"id":"d","text":"Nothing — modern databases avoid the trade-off entirely","is_correct":false}],"explanation":"When nodes can't communicate, you either reject requests to stay consistent (CP) or serve possibly-stale data to stay available (AP). Partition tolerance itself is non-negotiable."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
