INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('d90a3b51-4f7d-5094-8321-1f2aad44ce7b', '967bff6d-faab-5a6f-8145-eaa7bf8064a4', 1, $json${"prompt":"What is the first step in almost every interval problem (merge, insert, non-overlapping)?","multiple":false,"options":[{"id":"a","text":"Sort the intervals by start time","is_correct":true},{"id":"b","text":"Build an interval tree","is_correct":false},{"id":"c","text":"Convert intervals to a bitmap of covered points","is_correct":false},{"id":"d","text":"Sort by interval length, shortest first","is_correct":false}],"explanation":"After sorting by start, overlap detection becomes a single linear pass comparing each interval with the last merged one — current.start ≤ prev.end means overlap."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('712549bb-5458-5e23-9770-b6e7d080d4a4', '00000000-0000-0000-0000-000000000001', 'mcq', 'In fixed-width integer languages, how do you compute a binary-search midpoint...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('83051ca1-7ce6-5b0b-8b85-dc235cac4726', '712549bb-5458-5e23-9770-b6e7d080d4a4', 1, $json${"prompt":"In fixed-width integer languages, how do you compute a binary-search midpoint without overflow?","multiple":false,"options":[{"id":"a","text":"mid = low + (high − low) / 2","is_correct":true},{"id":"b","text":"mid = (low + high) / 2 — it can never overflow","is_correct":false},{"id":"c","text":"mid = high / 2 + low","is_correct":false},{"id":"d","text":"Use floating point and round","is_correct":false}],"explanation":"(low + high) can exceed the integer max when both are large; low + (high − low)/2 keeps every intermediate value in range. A classic math-and-edge-cases interview probe."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

