INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('0e9f3c8e-e0b6-5fe1-a96e-bb49c7211be9', '5e4cfa95-5758-5cc7-80bc-d1c181aa4caf', 1, $json${"prompt":"Which design pattern lets you swap algorithms at runtime behind one interface — e.g. multiple payment providers?","multiple":false,"options":[{"id":"a","text":"Strategy","is_correct":true},{"id":"b","text":"Singleton","is_correct":false},{"id":"c","text":"Decorator","is_correct":false},{"id":"d","text":"Observer","is_correct":false}],"explanation":"Strategy encapsulates interchangeable behaviors behind a common interface chosen at runtime. Decorator adds responsibilities, Observer broadcasts events, Singleton restricts instantiation."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('4a9b0895-d5dc-5802-9263-01c6a41150d2', '00000000-0000-0000-0000-000000000001', 'mcq', 'A table is in third normal form (3NF) when…', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('a6c5340f-60e3-5f0c-bf56-3629ef9de07e', '4a9b0895-d5dc-5802-9263-01c6a41150d2', 1, $json${"prompt":"A table is in third normal form (3NF) when…","multiple":false,"options":[{"id":"a","text":"Every non-key column depends on the key, the whole key, and nothing but the key","is_correct":true},{"id":"b","text":"It has no more than three foreign keys","is_correct":false},{"id":"c","text":"All columns are indexed","is_correct":false},{"id":"d","text":"Every query touches at most three tables","is_correct":false}],"explanation":"3NF removes transitive dependencies: non-key attributes may not depend on other non-key attributes. The mnemonic 'the key, the whole key, and nothing but the key' covers 1NF→3NF."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('b8b5cadf-ae54-56d4-a173-3938573573ce', '00000000-0000-0000-0000-000000000001', 'mcq', 'When would you deliberately denormalize a schema?', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('977d8a84-7fbc-5b36-809b-edbbea085bc4', 'b8b5cadf-ae54-56d4-a173-3938573573ce', 1, $json${"prompt":"When would you deliberately denormalize a schema?","multiple":false,"options":[{"id":"a","text":"When read-heavy access patterns make join cost dominate and duplicated data can be kept consistent","is_correct":true},{"id":"b","text":"Whenever a table exceeds one million rows","is_correct":false},{"id":"c","text":"Never — normalization is always superior","is_correct":false},{"id":"d","text":"When you need more foreign keys","is_correct":false}],"explanation":"Denormalization trades write complexity (keeping copies in sync) for read speed (no joins). It's a measured response to real read patterns — feed timelines, counters, reporting tables — not a row-count rule."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

