INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5d01ed9a-d640-5c79-8062-c97bc66fa6cb', '6576c335-6bbf-5ab8-a3af-5796baf404b7', 1, $json${"prompt":"What should you do FIRST when given a coding problem in an interview?","multiple":false,"options":[{"id":"a","text":"Restate the problem, ask clarifying questions, and confirm constraints and edge cases","is_correct":true},{"id":"b","text":"Start typing the brute-force solution immediately","is_correct":false},{"id":"c","text":"Ask for a hint to save time","is_correct":false},{"id":"d","text":"Write all the test cases before discussing the approach","is_correct":false}],"explanation":"Interviewers grade the process: restating catches misunderstandings when they're free to fix, and constraints (input size, value ranges, duplicates?) determine which complexity class is acceptable."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

