INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('57770de3-21d8-5403-b19b-2cafc48db1ef', '9409a1b3-61ee-57de-ab0b-4058b7bb096f', 1, $json${"prompt":"In a full-stack interview asking for a Todo app, which answer demonstrates senior judgment?","multiple":false,"options":[{"id":"a","text":"Start with the data model and API contract, then build UI state on top, mentioning optimistic updates and error rollback","is_correct":true},{"id":"b","text":"Install as many libraries as possible to show ecosystem knowledge","is_correct":false},{"id":"c","text":"Build the CSS animations first for visual impact","is_correct":false},{"id":"d","text":"Refuse to discuss the frontend because backend matters more","is_correct":false}],"explanation":"Schema and API contract are the load-bearing decisions — UI follows from them. Mentioning optimistic updates with rollback shows you've handled real client-server state, which is what the question probes."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
