INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('a2d2279a-16a0-58a7-a5dc-7369434e5df7', '56135c05-6df0-54a1-bc57-849ac25d160a', 1, $json${"prompt":"Two days before the interview, which practice plan is right?","multiple":false,"options":[{"id":"a","text":"Light review of patterns and notes — no new topics, protect sleep","is_correct":true},{"id":"b","text":"Grind 20 new hard problems to peak at the right moment","is_correct":false},{"id":"c","text":"Learn one new topic per remaining day for maximum coverage","is_correct":false},{"id":"d","text":"Stop all preparation a week early","is_correct":false}],"explanation":"Cramming new material this late adds anxiety, not ability — recall under pressure comes from consolidation and rest. Day 42 in the roadmap is literally 'Light Practice and Rest'."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

