INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('2a4a3a80-8a81-585e-a5db-0bfca5a901f1', '139597b9-9876-511b-8b8e-27f7c9791001', 1, $json${"prompt":"The most effective way to spend Week 6's weakness-focus days is:","multiple":false,"options":[{"id":"a","text":"Re-drill the specific patterns your mock-interview log flagged, hardest weakness first","is_correct":true},{"id":"b","text":"Re-solve Week 1's easy problems for confidence","is_correct":false},{"id":"c","text":"Read solutions without coding to cover more ground","is_correct":false},{"id":"d","text":"Practice only the topic you enjoy most","is_correct":false}],"explanation":"Week 5's mock log exists precisely to aim Week 6. Deliberate practice targets the edge of your ability — reading solutions or replaying strengths feels good but doesn't move the needle."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

