VALUES ('db1fd25b-f003-5cba-8efe-5cae977af24b', '00000000-0000-0000-0000-000000000001', 'mcq', 'During final DSA review, which signal says a pattern is genuinely interview-r...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('26841c7a-06ab-56f5-b78e-1fe352050e61', 'db1fd25b-f003-5cba-8efe-5cae977af24b', 1, $json${"prompt":"During final DSA review, which signal says a pattern is genuinely interview-ready?","multiple":false,"options":[{"id":"a","text":"You can identify the pattern from a fresh problem statement and code it without reference in ~20 minutes","is_correct":true},{"id":"b","text":"You recognize the solution when you read it","is_correct":false},{"id":"c","text":"You've watched three videos about it","is_correct":false},{"id":"d","text":"You solved it once, three weeks ago","is_correct":false}],"explanation":"Recognition is not recall. The interview demands generation under time pressure — if you can't produce the code cold on a NEW instance of the pattern, it goes back on the weakness list."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('3b8c987c-6d80-59bd-9e99-3e2eec0be7d2', '00000000-0000-0000-0000-000000000001', 'mcq', 'The night before the interview, the roadmap''s advice amounts to:', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('6ee3714a-e4fa-5102-9256-2bc06d72a442', '3b8c987c-6d80-59bd-9e99-3e2eec0be7d2', 1, $json${"prompt":"The night before the interview, the roadmap's advice amounts to:","multiple":false,"options":[{"id":"a","text":"Brief pattern skim, prepare clothes/setup, full night of sleep","is_correct":true},{"id":"b","text":"An all-nighter reviewing every topic once more","is_correct":false},{"id":"c","text":"Three timed mock interviews to stay sharp","is_correct":false},{"id":"d","text":"Learning that one system design topic you skipped","is_correct":false}],"explanation":"Sleep consolidates memory and powers the working memory you'll lean on tomorrow. Trading it for one more pass is strictly negative expected value."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('2fb72285-3d96-5634-9812-cceb569a29d8', '00000000-0000-0000-0000-000000000001', 'mcq', 'An interview went badly this morning; another is tomorrow (Day 43→44). What...', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('d69a479b-20f8-586f-b99a-7f91a2496055', '2fb72285-3d96-5634-9812-cceb569a29d8', 1, $json${"prompt":"An interview went badly this morning; another is tomorrow (Day 43→44). What now?","multiple":false,"options":[{"id":"a","text":"Write down what went wrong, fix anything fixable tonight, then mentally close it — tomorrow is independent","is_correct":true},{"id":"b","text":"Cancel tomorrow's interview — momentum is gone","is_correct":false},{"id":"c","text":"Stay up all night drilling the topic you missed","is_correct":false},{"id":"d","text":"Assume the worst and stop preparing entirely","is_correct":false}],"explanation":"One data point, one lesson, then reset: interviews are independent trials, and carrying this morning's anxiety into tomorrow is the only way it can actually hurt you. The roadmap schedules interviews on consecutive days for exactly this resilience."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

